package com.swingtrade.data.store;
import com.swingtrade.data.entity.LlmAnalysisResultEntity; import com.swingtrade.data.repository.LlmAnalysisResultRepository; import com.swingtrade.domain.LlmAnalysisResult; import com.swingtrade.domain.store.LlmAnalysisResultStore; import org.springframework.stereotype.Service; import java.time.LocalDate; import java.util.Optional;
@Service public class LlmAnalysisResultStoreImpl implements LlmAnalysisResultStore {private final LlmAnalysisResultRepository repo; public LlmAnalysisResultStoreImpl(LlmAnalysisResultRepository repo){this.repo=repo;} public Optional<LlmAnalysisResult> findBySymbolAndDate(String s,LocalDate d){return repo.findBySymbolAndAnalysisDate(s,d).map(LlmAnalysisResultEntity::toDomain);} public LlmAnalysisResult save(LlmAnalysisResult r){return repo.save(LlmAnalysisResultEntity.fromDomain(r)).toDomain();} public LlmAnalysisResult saveOrUpdate(LlmAnalysisResult r){var e=repo.findBySymbolAndAnalysisDate(r.symbol(),r.analysisDate()).orElseGet(LlmAnalysisResultEntity::new);var n=LlmAnalysisResultEntity.fromDomain(r);n.setId(e.getId());return repo.save(n).toDomain();}}
